ROOT = Path(__file__).resolve().parents[1]
REFERENCE = ROOT / 'reports/РПЗ_Горбунов_МГМО_NoisyNets_для_отправки.docx'
FINAL = ROOT / 'reports/РПЗ_Горбунов_МГМО_NoisyNets_итоговая.docx'
QA = ROOT / 'tmp/full-report'
REFERENCE_HASH = '6b2950ea9d19547cf8d93992a1405fec962433e8d8ee17ab028f4d622615805c'
W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
NS = {'w': W, 'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}


def load_csv(name):
    with (ROOT / 'results/final_analysis' / name).open(encoding='utf-8') as f:
        return list(csv.DictReader(f))


def f(value, digits=2):
    return f'{float(value):.{digits}f}'.replace('.', ',').replace('-', '−')


def pm(row, metric='final'):
    return f"{f(row[metric+'_mean'])} ± {f(row[metric+'_seed_sd'])}"


def pct(value):
    return f(float(value) * 100, 1) + ' %'


def interval(row):
    return f"[{f(row['ci95_low'])}; {f(row['ci95_high'])}]"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--page-map', type=Path, default=ROOT / 'reports/final_page_map.json',
                        help='Кэш страниц из проверенного PDF')
    args = parser.parse_args()
    assert sha256(REFERENCE.read_bytes()).hexdigest() == REFERENCE_HASH
    QA.mkdir(parents=True, exist_ok=True)
    conditions = load_csv('conditions.csv')
    runs = load_csv('per_run.csv')
    assert len(runs) == 80 and len(conditions) == 8
    cond = {(r['environment'], r['condition']): r for r in conditions}
    with (ROOT/'results/policy_analysis/conditions.csv').open(encoding='utf-8') as stream:
        policy_conditions = list(csv.DictReader(stream))
    with (ROOT/'results/policy_analysis/comparisons.csv').open(encoding='utf-8') as stream:
        policy_comparisons = list(csv.DictReader(stream))
    pol = {(r['environment'],r['condition']):r for r in policy_conditions}
    assert len(pol)==12
    cartpole = json.loads((ROOT / 'results/cartpole_analysis/summary.json').read_text())
    cartpole_old = {row['model']: row for row in cartpole['groups'] if not row['updated']}
    cartpole_new = [row for row in cartpole['groups'] if row['updated']]
    assert len(cartpole_new) == 8
    cartpole_steps = sum(row['config']['steps'] * 10 for row in cartpole_new)
    cartpole_steps_text = f'{cartpole_steps:,}'.replace(',', '\u00a0')
    cartpole_passed = sum(row['modes'][row['primary_mode']]['solved'] for row in cartpole_new)
    stopping = json.loads((ROOT / 'results/cartpole_dqn_stopping/analysis/summary.json').read_text())
    assert stopping['n_training_runs'] == 20 and stopping['exact_checkpoint_verification']['all_match']
