    comparisons = load_csv('comparisons.csv') + load_csv('ablations.csv')
    stochastic_comparisons = load_csv('stochastic_comparisons.csv')
    def comparison(env, method, ref='dqn', metric='final_mean'):
        found = [r for r in comparisons if r['environment'] == env and
                 r['condition'] == method and r['reference'] == ref and r['metric'] == metric]
        assert len(found) == 1, (env, method, ref, metric)
        return found[0]
    cp_d, cp_n = cond['cartpole', 'dqn'], cond['cartpole', 'noisy']
    ac_d, ac_n = cond['acrobot', 'dqn'], cond['acrobot', 'noisy']
    page_map = json.loads(args.page_map.read_text())
